INSERT INTO `news` (`id`, `created_by`, `created_date`, `updated_by`, `updated_date`, `approved`, `approved_to`, `approved_by`, `approved_date`, `deleted`, `division_id`, `departement_id`, `start_date`, `finish_date`, `name`, `description`, `attachment`, `status`) VALUES
('20231218000001', 'admin', '2023-12-18 11:15:34', 'admin', '2023-12-20 10:48:52', NULL, NULL, NULL, NULL, 0, '20231020000001', '[\"20231020000014\"]', '2023-12-18', '2023-12-22', 'Pengisian dan Verifikasi Dokumen', '<p style=\"text-align: left; font-size: 18px; line-height: 1.6; word-break: break-word; color: rgb(19, 53, 83); font-family: Inter, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"font-size: 12px;\">Menindaklanjuti surat plt. Direktur Pembelajaran dan Kemahasiswaan Nomor 0922/E2/DT.01.01/2023 tanggal 28 Februari 2023 perihal Pengisian Sistem Informasi Tata Kelola Kemahasiswaan (SIMKATMAWA) yang pada pokok surat tersebut diinformasikan bahwa batas akhir pelaporan dokumen tahun 2023 sampai dengan tanggal 30 November 2023 yang selanjutnya akan dilakukan verifikasi pada bulan Desember 2023.</span></p><p style=\"font-size: 18px; line-height: 1.6; word-break: break-word; color: rgb(19, 53, 83); font-family: Inter, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"font-size: 12px;\">Sehubungan dengan hal tersebut dimohon kepada Bapak/Ibu pimpinan perguruan tinggi untuk memperhatikan batas akhir pelaporan dan perlu disampaikan untuk pengumuman hasil verifikasi dokumen 2022 dan 2023 akan diumumkan bersamaan pada bulan Januari 2024 melalui akun perguruan&nbsp;</span>tinggi masing-masing.</p><p style=\"font-size: 18px; line-height: 1.6; word-break: break-word; color: rgb(19, 53, 83); font-family: Inter, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"font-size: 12px;\">Atas perhatian dan kerja sama Bapak/Ibu, disampaikan terima kasih.</span></p>', '1702874175.jpg', 0),
('20231218000002', 'admin', '2023-12-18 11:48:27', 'admin', '2023-12-18 17:16:09', NULL, NULL, NULL, NULL, 0, '20231020000003', '[\"20231020000002\"]', '2023-12-18', '2023-12-22', 'Hasil Seleksi Program Peningkatan Kemampuan Bahasa', '<p style=\"font-size: 18px; line-height: 1.6; word-break: break-word; color: rgb(19, 53, 83); font-family: Inter, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"font-size: 12px;\">Menindaklanjuti surat kami nomor: 4506/E4/DT.04.02/2023 tanggal 7 September 2023 perihal “Tawaran</span><br>Pendaftaran Program Peningkatan Kemampuan Bahasa Inggris (PKBI) Tahun 2023″, bersama ini kami<br>sampaikan daftar nama dosen yang dinyatakan lolos seleksi sebagai peserta Program PKBI Tahun 2023<br>sebagaimana terlampir.<br><br>Peserta sebagaimana tersebut di atas wajib mengikuti tata tertib sebagai berikut:</p><ol style=\"padding-left: 16px; font-size: 18px; color: rgb(19, 53, 83); font-family: Inter, Roboto, Helvetica, Arial, sans-serif;\"><li style=\"margin-bottom: 8px;\"><span style=\"font-size: 12px;\">Peserta wajib mengisi borang konfirmasi keikutsertaan Program PKBI melalui</span><br>http://ringkas.kemdikbud.go.id/konfirmasiPKBI2023 paling lambat 15 Oktober 2023 pukul<br>24.00 WIB. Bagi peserta yang tidak melengkapi borang sampai dengan tanggal yang telah<br>ditentukan maka akan dianggap mengundurkan diri.</li><li style=\"margin-bottom: 8px;\"><span style=\"font-size: 12px;\">Peserta wajib mengikuti kegiatan orientasi/pembukaan program sesuai jadwal yang akan</span><br>diinformasikan kemudian.</li><li style=\"margin-bottom: 8px;\"><span style=\"font-size: 12px;\">Peserta wajib mengikuti pelatihan bahasa Inggris selama 2 (dua) bulan secara intensif sesuai</span><br>jadwal dan lokasi yang telah ditetapkan oleh Direktorat Sumber Daya.</li><li style=\"margin-bottom: 8px;\"><span style=\"font-size: 12px;\">Direktorat Sumber Daya akan menanggung biaya pelatihan bahasa Inggris sesuai jadwal yang telah</span><br>ditentukan, biaya tes IELTS sebanyak 1 (satu) kali di akhir pelatihan, dan biaya lain sesuai<br>ketentuan yang berlaku.</li><li style=\"margin-bottom: 8px;\"><span style=\"font-size: 12px;\">Apabila peserta mengundurkan diri selama periode pelaksanaan program dan/atau tidak dapat</span><br>memenuhi syarat minimal kehadiran, kecuali sakit dan rawat inap (dibuktikan dengan surat<br>keterangan dari rumah sakit), maka peserta wajib mengembalikan dana yang telah dikeluarkan<br>oleh Direktorat Sumber Daya bagi yang bersangkutan.</li></ol>', '1702874908.png', 0),
('20240119000001', 'admin', '2024-01-19 21:01:37', 'admin', '2024-02-29 21:58:23', NULL, NULL, NULL, NULL, 0, '20231020000001', '[\"20231020000014\"]', '2024-01-15', '2024-03-01', 'Pengumuman Naik Gaji 2024', '<p style=\"margin-bottom: 20px; display: inline; font-family: Arial, Helvetica, Tahoma; font-size: 17px;\"><span style=\"font-size: 12px;\">Menteri Keuangan Sri Mulyani Indrawati angkat suara mengenai kenaikan gaji Aparatur Sipil Negara (ASN) pada tahun 2024 mendatang. Nantinya Presiden Joko Widodo&nbsp;(Jokowi) bakal mengumumkan pada saat penyampaian Rancangan Undang - Undang (RUU) APBN 2024 nanti.</span></p><p style=\"margin-top: 16px; margin-bottom: 20px; font-family: Arial, Helvetica, Tahoma; font-size: 17px;\"></p><p style=\"margin-bottom: 20px; font-family: Arial, Helvetica, Tahoma; font-size: 17px;\"><span style=\"font-size: 12px;\">\"Bapak presiden nanti akan sampaikan RUU APBN 2024 ya pada tanggal 16 Agustus, salah satu yang sedang kita hitung secara serius detil adalah kenaikan gaji ASN, TNI, Polri dan Pensiunan, jadi supaya enak dan tegang terus (tunggu) tanggal 16 Agustus pak Presiden,\" kata Sri Mulyani, di kompleks Istana Kepresidenan, Jakarta, Selasa (30/5/2023).</span></p>', '1705672898.jpg', 0);
